use std::fs

fn best(prios: Vec<int>) -> int {
    let mut bi: int = -1
    let mut i: int = 0
    while i < prios.len() as int {
        if bi < 0 || prios[i as usize] > prios[bi as usize] {
            bi = i
        }
        i += 1
    }
    bi
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut prios: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() == 0 {
            println("error")
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "add" && parts.len() == 3 {
            match parts[2].parse::<int>() {
                Ok(p) => {
                    names.push(parts[1].clone())
                    prios.push(p)
                }
                Err(_) => println("error")
            }
        } else if cmd == "pop" && parts.len() == 1 {
            let b = best(prios.clone())
            if b < 0 {
                println("empty")
            } else {
                println("${names[b as usize]}")
                names.remove(b as usize)
                prios.remove(b as usize)
            }
        } else if cmd == "peek" && parts.len() == 1 {
            let b = best(prios.clone())
            if b < 0 {
                println("empty")
            } else {
                println("${names[b as usize]}")
            }
        } else if cmd == "size" && parts.len() == 1 {
            println("${names.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while names.len() > 0 {
        let b = best(prios.clone())
        println("${names[b as usize]} ${prios[b as usize]}")
        names.remove(b as usize)
        prios.remove(b as usize)
    }
}

